const $=s=>document.querySelector(s);let state;try{state=JSON.parse(localStorage.getItem('actionlab-v1'))}catch{}state=Object.assign({done:[],labels:[],experiments:[],quiz:[],reflection:''},state||{});let page=0,action='走路',playing=true,points=true,t=0,last=0,observed=0;const names=['观察动作','理解原理','动手标注','规则实验','迁移挑战'];function save(){try{localStorage.setItem('actionlab-v1',JSON.stringify(state))}catch{}update()}function update(){let n=state.done.length;$('#percent').textContent=Math.round(n/5*100)+'%';$('#bar').value=n;$('#nav').innerHTML=names.map((n,i)=>`<button class="${page===i?'active':''}" onclick="go(${i})"><span>${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${n}</button>`).join('')}function complete(i){if(!state.done.includes(i))state.done.push(i);save()}function go(i){page=i;window.speechSynthesis?.cancel();render();update()}const head=(title,desc,tag)=>`<div class="sectionhead"><div><h2>${title}</h2><p>${desc}</p></div><span class="tag">${tag}</span></div>`;const stage=()=>`<div class="stage"><span class="overlay">POSE EXPLORER / 合成动作示范</span><span class="live">● 关键点可视化</span><canvas id="pose" aria-label="人体动作骨架动画"></canvas></div><div class="controls"><button onclick="playing=!playing;this.textContent=playing?'Ⅱ 暂停':'▶ 播放'">${playing?'Ⅱ 暂停':'▶ 播放'}</button><button onclick="points=!points;this.textContent=points?'隐藏关键点':'显示关键点'">${points?'隐藏关键点':'显示关键点'}</button><span>17 个关键点 · 教学动画</span></div>`;const next=(text,i)=>`<div class="nextbar"><span>每次动手，都让理解更进一步。</span><button class="primary" onclick="go(${i})">${text} →</button></div>`;function speak(text,id){if(!('speechSynthesis'in window)){$('#'+id).textContent='此浏览器不支持语音，请阅读下方讲解文字。';return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=.9;speechSynthesis.speak(u)}
const lesson='行为识别，是让计算机从连续画面中判断人正在做什么。第一步检测人体关键点，例如肩膀、髋部和膝盖。第二步计算特征，例如身体倾角和髋部高度变化。第三步结合连续多帧判断动作。坐下和跌倒可能在某一帧很相似，所以只看一张图容易误判。本课用规则分类器体验这个过程，真实模型还需要更多数据与验证。';
function render(){let el=$('#content');if(page===0){el.innerHTML=head('01 / 先看一看，机器看到了什么？','切换动作，观察人体关键点如何随时间变化。','观察任务 · 8 min')+`<div class="grid"><div class="card">${stage()}<div class="cardpad"><h3>同一个人，不同的动作语言</h3><div class="actions">${['走路','举手','下蹲','跌倒'].map(a=>`<button class="${action===a?'selected':''}" onclick="action='${a}';t=0;render()">${a}</button>`).join('')}</div><div class="note">观察提示：先看肩膀与髋部的连线，再看膝盖和脚踝。哪个变化最能帮助你区分动作？</div></div></div><div class="card cardpad"><div class="tasknum">THINK & TRY / 观察检查</div><div class="question">区分“坐下”和“跌倒”，<br>最值得观察什么？</div><p>先观看至少 6 秒动画，再选择你的判断。</p><div class="options"><button onclick="observeAnswer(false)">A　衣服的颜色</button><button onclick="observeAnswer(true)">B　身体姿态与连续运动变化</button><button onclick="observeAnswer(false)">C　单帧中人物的位置</button></div><div id="feedback" class="feedback" aria-live="polite">${state.done.includes(0)?'✓ 已完成观察检查。':''}</div><div class="note">学习目标<br>理解“识别动作”需要观察什么，而不只是记住动作名称。</div></div></div><div class="bottomcards"><div class="mini"><span>01</span><b>真看 · 观察差异</b><p>播放动作，发现身体姿态的变化。</p></div><div class="mini"><span>02</span><b>真听 · 带着问题</b><p>语音与文字同步提供，理解识别流程。</p></div><div class="mini"><span>03</span><b>真做 · 用结果说话</b><p>亲手标注、调参、验证，再解释。</p></div></div>`+next('进入原理讲解',1)}
if(page===1){el.innerHTML=head('02 / 从动作到判断，拆开智能的过程','听一段讲解，再用自己的判断连接三个步骤。','理解任务 · 7 min')+`<div class="card cardpad"><h3>机器的三步观察法</h3><button class="primary" id="listen">▷ 收听讲解</button> <button onclick="window.speechSynthesis?.cancel()">停止</button><p id="speechStatus" aria-live="polite"></p><p>${lesson}</p><div class="feature"><div class="card"><div class="big">01</div><h3>检测关键点</h3><p>把人体表示为肩、肘、髋、膝等点。低置信度的点需要过滤。</p></div><div class="card"><div class="big">02</div><h3>提取动作特征</h3><p>计算身体倾角、髋部高度和连续帧变化，形成可比较的数字。</p></div><div class="card"><div class="big">03</div><h3>结合时序判断</h3><p>用连续多帧减少单帧误判。规则阈值与数据驱动模型是不同方法。</p></div></div><div class="note">联系项目代码：source.py 使用头部、髋部和双腿方向等条件判断跌倒，并通过状态队列观察持续性。本课的阈值实验是简化的教学规则。</div><h3 style="margin-top:24px">检查理解：为什么不能只看一帧？</h3><div class="options"><button onclick="concept(false)">因为每张图片都无法检测关键点</button><button onclick="concept(true)">坐下与跌倒可能姿态相似，需要比较运动变化</button></div><div class="feedback" id="feedback" aria-live="polite"></div></div>`+next('开始标注数据',2);$('#listen').onclick=()=>speak(lesson,'speechStatus')}
if(page===2){let n=state.labels.length;el.innerHTML=head('03 / 你来当数据标注员','观察合成动作，为 4 个样本贴上准确标签。','动手任务 · 8 min')+(n<4?`<div class="grid"><div class="card">${stage()}<div class="cardpad"><h3>样本 ${n+1} / 4</h3><p>请根据身体变化判断动作。标签是模型学习与评估的重要基础。</p></div></div><div class="card cardpad"><div class="tasknum">LABEL THE MOTION</div><div class="question">这个人正在做什么？</div><div class="options">${['走路','举手','下蹲','跌倒'].map(a=>`<button onclick="label('${a}')">${a}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><button id="labelNext" hidden onclick="render()">下一个样本 →</button></div></div>`:`<div class="card cardpad"><h3>标注完成：${state.labels.filter(x=>x.correct).length} / 4 正确</h3>${state.labels.map((x,i)=>`<div class="sample"><span>样本 ${i+1} · 你的标签：${x.answer}</span><span>${x.correct?'✓ 正确':'需修正 → '+x.truth}</span></div>`).join('')}<p>举手看手腕高度，下蹲看髋部下降及膝关节弯曲，跌倒还要关注躯干倾斜和时间变化。</p><button onclick="state.labels=[];state.done=state.done.filter(x=>x!==2);save();render()">重新练习</button></div>`)+next('进入规则实验',3);if(n<4){action=['举手','下蹲','走路','跌倒'][n];t=0}}
if(page===3){el.innerHTML=head('04 / 给机器一条规则，看看它会犯什么错','调整身体倾角阈值，在固定验证集上比较误报和漏报。','实验任务 · 12 min')+`<div class="grid"><div class="card cardpad"><div class="tasknum">RULE CLASSIFIER / 规则分类实验</div><h3>如果身体倾角 ≥ 阈值，则预测为跌倒</h3><p>倾角定义：躯干相对竖直方向的夹角。这里只用一个特征，故意保留难例。</p><label for="threshold">倾角阈值 <strong id="angle">55°</strong></label><input id="threshold" type="range" min="20" max="85" value="55"><p>20° · 更敏感 <span style="float:right">更严格 · 85°</span></p><button class="primary" onclick="experiment()">▶ 运行验证</button><div id="results" class="feedback" aria-live="polite">调节滑块，然后运行验证。至少比较两个不同阈值并回答下面的问题。</div><div id="history"></div></div><div class="card cardpad"><h3>验证数据 · 8 个合成样本</h3>${data.map(x=>`<div class="sample"><span>${x.name}</span><span>${x.angle}° / ${x.fall?'跌倒':'非跌倒'}</span></div>`).join('')}<div class="note">误报：正常动作被判跌倒。<br>漏报：实际跌倒没有被检出。<br>此小型数据集仅用于学习，不代表真实准确率。</div></div></div><div class="card cardpad" style="margin-top:22px"><h3>实验思考：为什么阈值越低，误报通常越多？</h3><div class="options"><button onclick="experimentAnswer(true)">更多正常倾斜姿态也会跨过判断阈值</button><button onclick="experimentAnswer(false)">降低阈值会自动增加训练数据</button></div><div id="feedback" class="feedback" aria-live="polite"></div></div>`+next('完成迁移挑战',4);$('#threshold').oninput=e=>$('#angle').textContent=e.target.value+'°';history()}
if(page===4){el.innerHTML=head('05 / 把理解带到新的场景','完成 3 道挑战，并留下你的改进方案。','迁移任务 · 10 min')+`<div class="card cardpad">${quiz.map((q,i)=>`<h3 style="margin-top:22px">${i+1}. ${q.q}</h3><div class="options">${q.a.map((a,j)=>`<button class="${state.quiz[i]===j?'selected':''}" onclick="state.quiz[${i}]=${j};save();render()">${String.fromCharCode(65+j)}　${a}</button>`).join('')}</div>`).join('')}<h3 style="margin-top:25px">你的改进方案</h3><p>如果弯腰捡东西也触发了跌倒警报，你会补充什么特征或数据？至少写 15 个字。</p><textarea id="reflection" placeholder="例如：我会观察连续多帧中……"></textarea><div class="actions"><button class="primary" onclick="submitQuiz()">提交挑战</button><button onclick="downloadReport()">↓ 导出学习报告</button></div><div id="feedback" class="feedback" aria-live="polite"></div><div class="note">学习记录保存在此浏览器。报告包含你的作答、标注、实验与反思，可提交给老师。动画与规则演示不等同于真实视频识别。</div></div>`;$('#reflection').value=state.reflection;$('#reflection').oninput=e=>{state.reflection=e.target.value;save()}}}
function observeAnswer(ok){if(observed<6){$('#feedback').textContent='请先播放观察至少 6 秒，再作答。';return}$('#feedback').textContent=ok?'✓ 正确！动作不仅是姿态，也是姿态随时间的变化。':'再观察一下：颜色和单帧位置无法稳定区分这两种行为。';if(ok)complete(0)}function concept(ok){$('#feedback').textContent=ok?'✓ 正确！时序信息帮助我们区分相似姿态。':'关键点可以在单帧中检测，但动作往往需要多帧判断。';if(ok)complete(1)}function label(a){let n=state.labels.length;if(n>=4||!$('#labelNext').hidden)return;let truth=['举手','下蹲','走路','跌倒'][n];state.labels.push({answer:a,truth,correct:a===truth});$('#feedback').textContent=a===truth?'✓ 标注正确。':'本样本为“'+truth+'”。请注意手腕高度、髋部高度及身体方向的变化。';document.querySelectorAll('.options button').forEach(b=>b.disabled=true);$('#labelNext').hidden=false;$('#labelNext').textContent=n===3?'查看标注结果 →':'下一个样本 →';if(n===3)complete(2);save()}
const data=[{name:'正常站立',angle:5,fall:false},{name:'向前走路',angle:16,fall:false},{name:'坐下休息',angle:28,fall:false},{name:'弯腰捡物',angle:62,fall:false},{name:'伸展身体',angle:46,fall:false},{name:'侧向跌倒',angle:72,fall:true},{name:'前倾跌倒',angle:58,fall:true},{name:'躺倒过程',angle:81,fall:true}];function experiment(){let threshold=Number($('#threshold').value),tp=0,tn=0,fp=0,fn=0;data.forEach(x=>{let pred=x.angle>=threshold;if(pred&&x.fall)tp++;else if(pred)fp++;else if(x.fall)fn++;else tn++});let r={threshold,tp,tn,fp,fn,accuracy:(tp+tn)/8};state.experiments.push(r);save();$('#results').innerHTML=`<div class="big">${(r.accuracy*100).toFixed(1)}%</div>验证集准确率　/　正确 ${tp+tn} / 8<br>误报 ${fp} 次　·　漏报 ${fn} 次<br>召回率 ${(tp/3*100).toFixed(1)}%（正确检出 ${tp} / 3 个跌倒）`;history()}function history(){if($('#history'))$('#history').innerHTML=state.experiments.slice(-5).map(x=>`<div class="sample"><span>阈值 ${x.threshold}°</span><span>准确率 ${(x.accuracy*100).toFixed(1)}% · 误报 ${x.fp} · 漏报 ${x.fn}</span></div>`).join('')}function experimentAnswer(ok){if(new Set(state.experiments.map(x=>x.threshold)).size<2){$('#feedback').textContent='请先运行至少两个不同阈值的验证，比较结果后再回答。';return}$('#feedback').textContent=ok?'✓ 正确！要平衡误报和漏报，还可以加入运动速度与持续时间。':'再想一想：阈值改变判断边界，并不会改变数据量。';if(ok)complete(3)}
const quiz=[{q:'换到光线较暗的教室，系统效果变差，首先应该做什么？',a:['收集不同光照的数据，检查关键点质量并重新验证','只把阈值调到最大','继续使用原准确率宣传'],correct:0},{q:'怎样更可靠地评估识别效果？',a:['用训练过的同一批样本反复测试','用未参与调参的独立测试数据，检查误报与漏报','只保留预测正确的片段'],correct:1},{q:'为课堂收集真人动作视频时，应该怎么做？',a:['默认同学都同意被拍摄','把视频直接公开发布','先获得同意，减少身份信息并约定用途和删除时间'],correct:2}];function submitQuiz(){if(quiz.some((q,i)=>!Number.isInteger(state.quiz[i]))){$('#feedback').textContent='请完成全部 3 道题。';return}if(state.reflection.trim().length<15){$('#feedback').textContent='请补充至少 15 个字的改进方案。';return}let score=quiz.filter((q,i)=>state.quiz[i]===q.correct).length;$('#feedback').innerHTML=`本次得分 ${score} / 3。<br>`+quiz.map((q,i)=>`${i+1}. ${state.quiz[i]===q.correct?'✓ 正确':'建议再思考：'+q.a[q.correct]}`).join('<br>');if(score===3)complete(4);save()}function downloadReport(){let report={course:'行知实验室 · 行为识别入门',exportedAt:new Date().toISOString(),completed:state.done.map(i=>names[i]),labels:state.labels,experiments:state.experiments,quiz:quiz.map((q,i)=>({question:q.q,answer:q.a[state.quiz[i]]||'未作答',correct:state.quiz[i]===q.correct})),reflection:state.reflection};let blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='行为识别学习报告.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function draw(now){let dt=last?Math.min((now-last)/1000,.05):0;last=now;if(playing){t+=dt;if(page===0)observed+=dt}let c=$('#pose');if(c){let dpr=window.devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=w*dpr;c.height=h*dpr}let ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#2a453b';ctx.lineWidth=.6;for(let x=0;x<w;x+=35){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=35){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}let s=Math.min(w/440,h/310),cx=w*.48,cy=h*.52,phase=t*3,walk=action==='走路'?Math.sin(phase):0,squat=action==='下蹲'?(Math.sin(phase*.6)+1)/2:0,raise=action==='举手'?(Math.sin(phase*.65)+1)/2:0,fall=action==='跌倒'?(Math.sin(t*1.1-Math.PI/2)+1)/2:0;let pts=[[0,-99],[-7,-104],[7,-104],[-14,-99],[14,-99],[-25,-65],[25,-65],[-36,-22-raise*65],[36,-22-raise*65],[-40,14-raise*128],[40,14-raise*128],[-18,5],[18,5],[-20-walk*22-squat*25,53-squat*10],[20+walk*22+squat*25,53-squat*10],[-20+walk*25,102-squat*48],[20-walk*25,102-squat*48]];pts=pts.map(([x,y])=>{y+=squat*45;let angle=fall*1.38;return[cx+(x*Math.cos(angle)-y*Math.sin(angle))*s,cy+(x*Math.sin(angle)+y*Math.cos(angle)+fall*30)*s]});let edges=[[0,5],[0,6],[5,6],[5,7],[7,9],[6,8],[8,10],[5,11],[6,12],[11,12],[11,13],[13,15],[12,14],[14,16],[0,1],[0,2],[1,3],[2,4]];ctx.lineCap='round';ctx.lineWidth=points?3:8;edges.forEach(([a,b],i)=>{ctx.strokeStyle=i<8?'#a5dba4':'#62b7a2';ctx.beginPath();ctx.moveTo(...pts[a]);ctx.lineTo(...pts[b]);ctx.stroke()});if(points)pts.forEach(([x,y],i)=>{ctx.beginPath();ctx.fillStyle=i<5?'#f1dca2':'#d5edba';ctx.arc(x,y,4*s,0,7);ctx.fill()});ctx.strokeStyle='#71b69a66';ctx.setLineDash([5,5]);ctx.strokeRect(cx-110*s,cy-120*s,230*s,240*s);ctx.setLineDash([]);ctx.fillStyle='#b3d1bb';ctx.font='10px sans-serif';ctx.fillText(page===2?'SAMPLE '+(state.labels.length+1):action+' / 动态姿态',22,h-20);ctx.fillStyle='#7da88b';ctx.fillText('x →',w-50,h-20)}requestAnimationFrame(draw)}$('#teacher').onclick=()=>$('#guide').showModal();$('#closeGuide').onclick=()=>$('#guide').close();go(0);requestAnimationFrame(draw);
